"""Create an offline, English report with filtering and printing."""
import html, json
from collections import Counter

def render_html(report, destination):
    rows=report['results']
    counts=Counter(r['function'] for r in rows)
    unit=html.escape(report.get('card_unit','test cases'))
    cards=''.join(f'<div class="card"><span>{html.escape(name)}</span><strong>{count}</strong><small>{unit}</small></div>' for name,count in counts.items())
    table=[]
    for r in rows:
        number=lambda key: f'{r[key]:.12g}'
        state=r['result'].lower()
        exact=r['absolute_difference']==0
        table.append(f'''<tr data-function="{r['function']}" data-status="{state}" data-exact="{str(exact).lower()}"><td>{r['test']}</td><td><span class="fn {r['function'].lower()}">{r['function']}</span></td><td class="inputs">{html.escape(r['inputs'])}</td><td>{number('original_x86')}</td><td>{number('rusttran')}</td><td class="{'zero' if exact else 'difference'}">{number('absolute_difference')}</td><td>{number('relative_difference')}</td><td>{r['float32_ulp'] if r['float32_ulp'] is not None else '—'}</td><td>{'Yes' if r['previous_derivative_matches'] else 'No' if r['previous_derivative_matches'] is False else '—'}</td><td><span class="badge {state}">{r['result']}</span></td></tr>''')
    options=''.join(f'<option>{name}</option>' for name in counts)
    limitations=''.join(f'<li>{html.escape(item)}</li>' for item in report['limitations'])
    document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RustTran · Numerical comparison</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#171b20;color:#e5e9ef}body{margin:0;padding:32px;max-width:1600px;margin:auto}h1{font-size:clamp(24px,4vw,38px);margin:6px 0 12px}.eyebrow{color:#ebc452;letter-spacing:.12em;font-size:12px}p,li{color:#b7c1ce;line-height:1.6}.summary{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.card{background:#252b33;border:1px solid #3a4552;border-radius:12px;padding:16px;min-width:115px}.card span,.card small{display:block;color:#b7c1ce}.card strong{display:block;font-size:30px;margin:5px 0;color:#ecc655}.card.total strong{color:#75dba7}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:20px 0}select,input,button{font:inherit;color:inherit;background:#282f39;border:1px solid #536070;border-radius:7px;padding:10px}button{cursor:pointer}button:hover{border-color:#ebc452}label{color:#c0cbd8}.table-wrap{overflow:auto;border:1px solid #3d4753;border-radius:10px;max-height:70vh}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:13px;font-variant-numeric:tabular-nums}th{position:sticky;top:0;background:#353e4a;color:#f4f7fc;text-align:right;padding:14px 12px;z-index:1}th:nth-child(2),th:nth-child(3){text-align:left}td{padding:11px 12px;text-align:right;border-bottom:1px solid #333c47}td:nth-child(2),td:nth-child(3){text-align:left}tr:nth-child(even){background:#21272f}tr:hover{background:#303b49}tr[hidden]{display:none}.inputs{font-family:ui-monospace,monospace}.fn,.badge{padding:4px 8px;border-radius:6px;font-weight:650}.decay{color:#f7d775;background:#52462a}.hfld{color:#85d1f6;background:#233e50}.hgas{color:#d1a8ff;background:#3e2c53}.vfld{color:#85e4d7;background:#234b45}.hliq{color:#ffbb89;background:#533c2a}.euler{color:#f49fc8;background:#4d2e42}.pass{color:#8ee7b6;background:#244938}.fail{color:#ffb0b0;background:#672c32}.zero{color:#80cba6}.difference{color:#f7cf72}details{background:#252b33;border-radius:10px;padding:18px;margin:24px 0}summary{cursor:pointer;color:#ecc655}.meta{font-size:12px;overflow-wrap:anywhere}#shown{color:#b7c1ce}a{color:#89caff}@media print{:root{color-scheme:light;background:white;color:#111}body{padding:0}.controls{display:none}.table-wrap{max-height:none;overflow:visible}th{position:static;background:#ddd;color:#111}td{color:#111}tr:nth-child(even){background:#f2f2f2}.card,details{background:#eee}.card span,.card small,p,li{color:#333}.card strong,.card.total strong{color:#111}details{display:block}table{font-size:9px}td,th{padding:6px}.badge,.fn{print-color-adjust:exact;-webkit-print-color-adjust:exact}}
</style><body>
<div class="eyebrow">RUSTTRAN / PCTRAN</div><h1>Numerical comparison</h1>
<p>Original x86 numerical helper instructions vs. the packaged RustTran CLI.<br><strong>This is not a comparison of complete reactor simulations.</strong> DECAY samples cover 0–300 seconds.</p>
<div class="summary"><div class="card total"><span>Passed / total</span><strong>__PASSED__ / __TOTAL__</strong><small>__EXACT__ exact numeric matches</small></div>__CARDS__</div>
<div class="controls"><label>Function <select id="function"><option value="">All functions</option>__OPTIONS__</select></label><label>Result <select id="status"><option value="">All results</option><option value="pass">PASS</option><option value="fail">FAIL</option></select></label><label><input type="checkbox" id="differences"> Nonzero differences only</label><button id="print">Print / save PDF</button><span id="shown"></span></div>
<div class="table-wrap"><table><thead><tr><th>Test</th><th>Function</th><th>Inputs</th><th>PCTran x86</th><th>RustTran</th><th>Absolute difference</th><th>Relative difference</th><th>Float32 ULP</th><th>Previous derivative matches</th><th>Result</th></tr></thead><tbody>__ROWS__</tbody></table></div>
<p>Acceptance: DECAY / HFLD / HGAS / VFLD ≤ 2 float32 ULP. HLIQ error ≤ max(1, |reference|) × 10⁻¹⁰. EULER error ≤ max(1, |reference|) × 10⁻⁷, with an exact previous derivative update. ULP means distance in representable float32 values; it is not used for HLIQ or EULER.</p>
<details open><summary>Method and limits</summary><ul>__LIMITS__</ul><p>Seed: __SEED__. Inputs: DECAY time in seconds; HFLD/HGAS/VFLD pressure in psia; HLIQ [pressure psia, temperature °F]; EULER [current derivative, previous derivative, time step, state]. EULER cases are isolated updates, not complete trajectories.</p><p><a href="results.csv">Download CSV</a> · <a href="results.json">JSON and original instruction evidence</a></p><p class="meta">PCTran SHA-256: __ORIGINAL__<br>RustTran CLI SHA-256: __RUST__</p></details>
<script>
const f=document.getElementById('function'),s=document.getElementById('status'),d=document.getElementById('differences'),rows=[...document.querySelectorAll('tbody tr')];
function filter(){let shown=0;for(const r of rows){r.hidden=!!((f.value&&r.dataset.function!==f.value)||(s.value&&r.dataset.status!==s.value)||(d.checked&&r.dataset.exact==='true'));if(!r.hidden)shown++;}document.getElementById('shown').textContent=`${shown} / ${rows.length} shown`;}
[f,s,d].forEach(x=>x.addEventListener('change',filter));document.getElementById('print').addEventListener('click',()=>window.print());filter();
</script></body></html>'''
    if report.get('report_intro'):
        document=document.replace('Original x86 numerical helper instructions vs. the packaged RustTran CLI.<br><strong>This is not a comparison of complete reactor simulations.</strong> DECAY samples cover 0–300 seconds.', html.escape(report['report_intro']))
    if report.get('acceptance_description'):
        old='Acceptance: DECAY / HFLD / HGAS / VFLD ≤ 2 float32 ULP. HLIQ error ≤ max(1, |reference|) × 10⁻¹⁰. EULER error ≤ max(1, |reference|) × 10⁻⁷, with an exact previous derivative update. ULP means distance in representable float32 values; it is not used for HLIQ or EULER.'
        document=document.replace(old,html.escape(report['acceptance_description']))
    if report.get('inputs_description'):
        old='Inputs: DECAY time in seconds; HFLD/HGAS/VFLD pressure in psia; HLIQ [pressure psia, temperature °F]; EULER [current derivative, previous derivative, time step, state]. EULER cases are isolated updates, not complete trajectories.'
        document=document.replace(old,html.escape(report['inputs_description']))
    document=document.replace('.pass{', '.phases{color:#d1a8ff;background:#3e2c53}.phasestate{color:#85e4d7;background:#234b45}.primaryflow{color:#85d1f6;background:#233e50}.heatcapacity{color:#ffbb89;background:#533c2a}.correction{color:#f49fc8;background:#4d2e42}.primarycore{color:#f7d775;background:#52462a}.normalphase{color:#85d1f6;background:#233e50}.inventory{color:#ffbb89;background:#533c2a}.sgglobal{color:#85e4d7;background:#234b45}.decayheat{color:#ffbb89;background:#533c2a}.modes{color:#85e4d7;background:#234b45}.feedwater{color:#85d1f6;background:#233e50}.primary{color:#d1a8ff;background:#3e2c53}.rcppair{color:#f7d775;background:#52462a}.liquid{color:#f49fc8;background:#4d2e42}.loops{color:#85d1f6;background:#233e50}.driving{color:#ffbb89;background:#533c2a}.transfer{color:#f7d775;background:#52462a}.reference{color:#85e4d7;background:#234b45}.properties{color:#d1a8ff;background:#3e2c53}.relief{color:#f7d775;background:#52462a}.saturated{color:#85d1f6;background:#233e50}.steam{color:#d1a8ff;background:#3e2c53}.controller{color:#85e4d7;background:#234b45}.activation{color:#ffbb89;background:#533c2a}.tank{color:#f49fc8;background:#4d2e42}.accumulator{color:#cbd8e8;background:#394657}.outflow{color:#f7d775;background:#52462a}.startup{color:#85d1f6;background:#233e50}.heat{color:#ffbb89;background:#533c2a}.restore{color:#85e4d7;background:#234b45}.pass{')
    replacements={'PASSED':str(report['passed']),'TOTAL':str(report['total']),'EXACT':str(sum(r['absolute_difference']==0 for r in rows)),'CARDS':cards,'OPTIONS':options,'ROWS':''.join(table),'LIMITS':limitations,'SEED':str(report['random_seed']),'ORIGINAL':report['original_sha256'],'RUST':report['rust_cli_sha256']}
    for name,value in replacements.items(): document=document.replace('__'+name+'__',value)
    destination.write_text(document)
